import os,json,subprocess,pathlib,shlex
root=pathlib.Path.cwd(); lab=root/'.test-lab'; home=lab/'agent-home'; cwd=lab/'agent-cwd'
home.mkdir(exist_ok=True);cwd.mkdir(exist_ok=True)
config={'hasCompletedOnboarding':True,'theme':'dark','bypassPermissionsModeAccepted':True,'projects':{str(cwd):{'hasTrustDialogAccepted':True,'hasCompletedProjectOnboarding':True}}}
(home/'.claude.json').write_text(json.dumps(config))
env={'PATH':os.environ['PATH'],'HOME':str(home),'CLAUDE_CONFIG_DIR':str(home),'TMPDIR':str(lab/'tmp'),'TERM':'xterm-256color','LANG':'en_US.UTF-8','ANTHROPIC_BASE_URL':'https://openrouter.ai/api','ANTHROPIC_API_KEY':'','CLAUDE_CODE_SIMPLE':'1','CLAUDE_CODE_ENABLE_PROMPT_SUGGESTION':'false','CLAUDE_CODE_SEND_FEEDBACK':'0','DISABLE_AUTOUPDATER':'1','CLAUDE_CODE_DISABLE_AUTO_MEMORY':'1'}
# Credentials remain only in process environment, never command text or artifacts.
subprocess.run(['tmux','-f','/dev/null','-S',str(lab/'tmux.sock'),'new-session','-d','-s','live','-n','worker','-x','180','-y','45','-c',str(cwd),'env -i '+ ' '.join(shlex.quote(k)+'='+shlex.quote(v) for k,v in env.items() if k!='CLAUDE_CODE_OAUTH_TOKEN')+' ANTHROPIC_AUTH_TOKEN="$OPENROUTER_API_KEY" '+shlex.quote(subprocess.check_output(['which','claude'],text=True).strip())+' --dangerously-skip-permissions --model cohere/north-mini-code:free --setting-sources local --append-system-prompt '+shlex.quote('You are a disposable test worker. Follow the self describing inbox doorbell, read all records in order, execute the harmless requested file operations, and move each record into handled as instructed. Stay inside '+str(root)+'.')+' --settings \'{"feedbackDrafts":"off","skipDangerousModePermissionPrompt":true,"claudeMdExcludes":["/**"]}\''],env=dict(os.environ, HOME=str(home)),check=True)
